<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;line-height:1.7;color:#222}.header{text-align:center;margin-bottom:45px}h1{font-size:20px}.amount{font-weight:bold}.signature{margin-top:70px;border-top:1px solid #555;width:240px;padding-top:5px}</style></head><body><div class="header"><h1>{{ $review->employee?->company?->name }}</h1><div>Compensation Revision Letter</div></div><p>Date: {{ now()->format('Y-m-d') }}</p><p>Dear {{ $review->employee?->full_name }},</p><p>Following the completed compensation review, your monthly salary has been revised from <span class="amount">{{ number_format($review->current_salary,2) }}</span> to <span class="amount">{{ number_format($review->approved_salary,2) }}</span>, effective {{ $review->effective_date->format('Y-m-d') }}.</p><p>{{ $review->reason }}</p><p>This revision is subject to the company's payroll policies and applicable statutory deductions.</p><p class="signature">Authorized HR / Payroll Signatory</p></body></html>
